add_action("init", function (): void {
    // Runs on every WordPress load, after WordPress is ready.
});
add_filter("the_title", function (string $title): string {
    return "Shop: " . $title;
});

$shopName = get_option("shop_name", "My Shop");
update_option("shop_name", "Prabh Store");
$posts = get_posts(["numberposts" => 5, "post_status" => "publish"]);
foreach ($posts as $post) {
    echo esc_html($post->post_title) . "\n";
}

add_shortcode("hello_shop", function (array $atts): string {
    $atts = shortcode_atts(["name" => "Guest"], $atts, "hello_shop");
    return "Hello, " . esc_html($atts["name"]) . "!";
});

if (have_posts()) {
    while (have_posts()) {
        the_post();
        the_title("<h2>", "</h2>");
        the_content();
    }
} else {
    echo "No posts found.";
}
